package ch.bbw.zork.rooms;/** * Author:  Michael Kolling, Version: 1.1, Date: August 2000 * refactoring: Rinaldo Lanza, September 2020 */import ch.bbw.zork.Direction;import ch.bbw.zork.furniture.Door;import ch.bbw.zork.furniture.Furniture;import java.util.HashMap;public abstract class Room {	private final String name;	private final String description;	private HashMap<Direction, Room> neighbors;	private HashMap<Direction, Door> exitDoors;	private Furniture[] furniture;	public Room(String name) {		/*this.name = name;		this.description = "";		this.neighbors = new HashMap<>();		this.exitDoors = new HashMap<>();*/		this(name, "");	}	public Room(String name, String description) {		/*this.name = name;		this.description = description;		this.neighbors = new HashMap<>();		this.exitDoors = new HashMap<>();*/		this(name, description, new HashMap<>(), new HashMap<>());	}	public Room(String name, String description, HashMap<Direction, Room> neighbors, HashMap<Direction, Door> exitDoors) {		this.name = name;		this.description = description;		this.neighbors = neighbors;		this.exitDoors = exitDoors;	}	public void setExitDoors(HashMap<Direction, Door> exitDoors) {		this.exitDoors = exitDoors;	}	public HashMap<Direction, Door> getExitDoors() {		return exitDoors;	}	public Door isExitLocked(Direction direction) {		return exitDoors.get(direction);	}	public String getDescription() {		return description;	}	public String getName() {		return name;	}	public Room getExit(Direction direction) {		return neighbors.get(direction);	}	public void setNeighbors(HashMap<Direction, Room> neighbors) {		this.neighbors = neighbors;	}	public void setFurniture(Furniture[] furniture) {		this.furniture = furniture;	}	public Furniture[] getFurniture() {		return furniture;	}}